-- | The class of a valid code, by its first digit (R HS:RFC9110-15-2).
{-@ reflect classOfCode @-}
classOfCode :: Int -> Class
classOfCode n
  | n < 200 = Informational
  | n < 300 = Successful
  | n < 400 = Redirection
  | n < 500 = ClientError
  | otherwise = ServerError

