-- | A status a response we send may carry: Permanent, and final rather than
-- interim. R HS:IANA-HTTP-Status-Codes-104, HS:IANA-HTTP-Status-Codes-510; P UP:RESUMABLE-UPLOAD-13-4.4.2-8, UP:RESUMABLE-UPLOAD-13-4.2.2-7 (PM10).
{-@ reflect respondable @-}
respondable :: Status -> Bool
respondable s = case registration s of
  Permanent -> case classOf s of
    Informational -> False
    _ -> True
  Temporary -> False
  Obsoleted -> False

