-- | V1: so no two constructors share a code.
{-@ statusCodeInjective :: a:Status -> b:{Status | statusCode a == statusCode b} -> {a == b} @-}
statusCodeInjective :: Status -> Status -> Proof
statusCodeInjective a b = () ? roundTrip a ? roundTrip b

